    "spokenText": "江南，汉乐府，汉代。江南可采莲，莲叶何田田。鱼戏莲叶间。鱼戏莲叶东，鱼戏莲叶西，鱼戏莲叶南，鱼戏莲叶北。",
    "translation": "江南水乡正是采莲的好时节，莲叶长得多茂盛多密呀！欢快的小鱼儿在茂密的荷叶间嬉戏追逐：一会儿游向东，一会儿游向西，一会儿游向南，一会儿游向北。",
    "appreciation": "这是一首生动清新的汉代民歌。通过东西南北四个方位的回环吟唱，把小鱼儿在荷叶下敏捷穿梭的灵动与采莲人的欢畅心情展现得淋漓尽致。",
