    "spokenText": "悯农其二，李绅，唐代。锄禾日当午，汗滴禾下土。谁知盘中餐，粒粒皆辛苦。",
    "translation": "烈日当空的中午，农民还在田里挥锄给禾苗松土除草。一滴滴辛勤的汗水，滴落在禾苗下的泥土里。有谁能想到餐盘里的每一粒香甜米饭，全都凝聚着庄稼人耕作的万般辛劳呢？",
    "appreciation": "这是一首家喻户晓的劝诫诗。诗句质朴真挚，教育小朋友们无论何时都要懂得尊重劳动成果，珍惜每一粒粮食，不剩饭不浪费。",
