    "spokenText": "古朗月行节选，李白，唐代。小时不识月，呼作白玉盘。又疑瑶台镜，飞在青云端。",
    "translation": "小的时候不认识天上的月亮，把它叫作纯净无瑕的白玉圆盘。有时又怀疑是仙人瑶台上的宝镜，飞到了九霄青云的最高处。",
    "appreciation": "诗仙李白以天真烂漫的儿童口吻，把一轮皎洁的圆月比作“白玉盘”和“瑶台镜”，充满了奇绝浪漫的飞扬想象，极富童心童趣。",
