    "translation": "我李白坐上小船刚要起锚出发，忽然听到岸上传来村民一边用脚打着节拍一边唱歌送行的声音。桃花潭的水纵然有千尺那么深，也比不上汪伦来送别我的深厚情谊呀！",
    "appreciation": "李白用桃花潭水的“深千尺”来比喻汪伦对自己的情意，把抽象看不见的情谊化作具体可感的深潭，真率自然，千百年来传为佳话。",
