    "translation": "小泉眼悄无声息地流淌，仿佛舍不得细细的泉水。浓密的树阴倒映在池水里，喜爱晴天里温柔明媚的风光。嫩绿娇小的新荷叶才刚刚露出尖尖小角，早有一只灵巧的蜻蜓轻盈地立在上面歇脚。",
    "appreciation": "宋代诗人杨万里善于捕捉大自然中最生动的初夏特写。一汪清池、一抹泉水、几片初绽荷叶与一只静立的蜻蜓，组合成一幅生机盎然的江南初夏油画。",
