    "spokenText": "画鸡，唐寅，明代。头上红冠不用裁，满身雪白走将来。平生不敢轻言语，一叫千门万户开。",
    "translation": "它头顶上天然长就一顶威风凛凛的红鸡冠，不用人工剪裁；一身洁白如雪的羽毛，威武昂扬地大步走来。平时从来不轻易啼叫鸣吵，只要它黎明一放声啼晓，千家万户的门扉就立刻敞开迎接晨曦。",
    "appreciation": "唐伯虎通过题画诗，既惟妙惟肖描摹了雄鸡神骏洁白的样貌，更赋予它报晓唤醒人间的崇高品格与雄伟气魄。",
