    "spokenText": "小儿垂钓，胡令能，唐代。蓬头稚子学垂纶，侧坐莓苔草映身。路人借问遥招手，怕得鱼惊不应人。",
    "translation": "一个头发蓬松的小男孩学着大人的模样在河边钓鱼，侧着身子坐在长满青苔的草地上，茂密的野草遮映着他小巧的身影。路上有行人走来向他打听道路，小男孩远远地直摆小手，生怕声音惊吓了水里即将上钩的小鱼，连话都不敢答应一声。",
    "appreciation": "形神兼备！诗人精准抓住了小男孩全神贯注钓鱼时“遥招手”这一生动细节，把儿童的天真专一、聪明可爱写得呼之欲出。",
