    "translation": "所有的群山中鸟儿都飞绝无影，所有的道路上行人的踪迹早已绝灭。在一只孤零零的小船上，坐着一位身披蓑衣、头戴斗笠的渔翁，独自一人在风雪交加的寒江上垂钓。",
    "appreciation": "这是一幅空旷孤寂的寒江飞雪图。柳宗元在万籁俱寂的纯白世界中，以孤舟钓叟的坚毅形象，表达了自己虽处逆境却傲骨凛然、不随波逐流的崇高人格。",
