    "spokenText": "敕勒歌，北朝民歌，南北朝。敕勒川，阴山下。天似穹庐，笼盖四野。天苍苍，野茫茫。风吹草低见牛羊。",
    "translation": "辽阔的敕勒大草原就在巍峨的阴山山脉脚下。苍穹宛如巨大的游牧毡帐，广阔无垠地笼罩着草原的四面八方。蓝天浩渺苍苍，原野辽阔苍茫。一阵阵清风吹过，茂密的牧草俯低下去，显现出肥硕成群的牛羊！",
    "appreciation": "北朝草原民歌的绝唱！格调雄健辽阔，气象苍茫。将天圆地方的宇宙感与草深羊肥的生机生动结合，歌颂了游牧民族热爱的锦绣山河。",
