    "spokenText": "咏柳，贺知章，唐代。碧玉妆成一树高，万条垂下绿丝绦。不知细叶谁裁出，二月春风似剪刀。",
    "translation": "高高的柳树宛如用晶莹的碧玉梳妆打扮而成，千千万万条嫩绿的柳丝像绿色的丝带一般轻柔下垂。不知道这精致纤细的柳叶是谁巧手裁剪出来的？原来是那温煦的二月春风，就像一把神奇灵动的剪刀！",
    "appreciation": "贺知章借咏柳以赞美春之生机。他把春风拟人化为巧夺天工的剪刀，构思奇妙，将抽象的春风化为剪裁绿意的大师，充满了生命律动。",
