    "translation": "古老平原上的野草长得多繁茂茂密啊，每年都要经历一次枯萎与一次繁盛。无情的野火无法将它的根脉烧绝烧尽，只要春风一吹，它又会顽强地破土生长！",
    "appreciation": "白居易十六岁考科举时的成名作。“野火烧不尽，春风吹又生”成为了中华民族坚韧不拔、自强不息顽强生命力的永恒图腾。",
