    "spokenText": "晓出净慈寺送林子方，杨万里，宋代。毕竟西湖六月中，风光不与四时同。接天莲叶无穷碧，映日荷花别样红。",
    "translation": "到底是六月份的西湖呀，那里的壮丽风光与一年中其他季节大不相同。那连绵无际的绿色荷叶一直延伸到天边，呈现出无边无际的浓绿；在早晨骄阳的映照下，盛开的荷花显得格外艳丽娇红！",
    "appreciation": "西湖荷花的千古绝唱！诗人以“无穷碧”与“别样红”相映衬，碧波连天，红日照耀，把六月西湖磅礴热烈的盛夏生命力展现得酣畅淋漓。",
