    "translation": "两只娇俏的黄鹂在翠绿的柳枝间欢快鸣叫，一行纯洁的白鹭排着整齐的队伍展翅飞上蔚蓝的晴空。推开窗户，一眼饱览西岭千年不化的积雪；门前江岸停泊着从万里之外东吴顺流远航而来的客船。",
    "appreciation": "诗圣杜甫在成都草堂写下的明快诗篇。全诗四句皆是对仗句，色彩绚烂（黄、翠、白、青），空间开阔（从眼前翠柳到九霄晴空，从千秋雪山到万里航船），心境开朗舒展。",
