    "spokenText": "舟夜书所见，查慎行，清代。月黑见渔灯，孤光一点萤。微微风簇浪，散作满河星。",
    "translation": "在没有月光的漆黑夜晚，江面上闪烁着一盏渔船上的孤灯，那微弱的一点亮光就像草丛中飞舞的萤火虫。一阵阵微风吹来掀起层层波浪，那一星微弱的渔火倒映在碎浪中，瞬间散碎成满河摇曳的璀璨繁星！",
    "appreciation": "诗人妙笔生花，抓住黑夜中“静”到“动”的光影变幻，前两句写静如一点萤火，后两句写动如银河碎星，虚实变幻，意趣横生。",
