    "translation": "国家要重新恢复勃勃生机，必须依靠狂风暴雨般的变革；人们沉默不语、万马齐喑的沉闷局面实在令人悲哀。我奉劝上天重新振奋精神，打破一切条框规矩降下优秀人才！",
