    "translation": "清晨幼童从铜盆里取出一整块冻结的冰块，用彩色丝线穿系起来当作银钲敲打。清脆的声音像玉磬一样在树林中回荡，忽然冰块掉落，发出像玻璃碎地一样的声响。",
