    "spokenText": "村晚，雷震，宋代。草满池塘水满陂，山衔落日浸寒漪。牧童归去横牛背，短笛无腔信口吹。",
    "translation": "池塘四周长满了青草，池水漫过了池岸；青山仿佛衔着落日，水波倒映着夕阳寒光。小牧童放牧归来横骑在黄牛背上，拿着短笛随心所欲无曲调地信口吹奏。",
    "appreciation": "夕阳斜照的水乡晚景与无忧无虑的牧童相映成趣。",
