    "spokenText": "游子吟，孟郊，唐代。慈母手中线，游子身上衣。临行密密缝，意恐迟迟归。谁言寸草心，报得三春晖。",
    "translation": "慈祥的母亲手里拿着针线，正为即将远行的儿子缝制衣衫。临出发前密密匝匝地缝缀，心里唯恐儿子在外逗留迟迟难归。有谁能说小草那一点点绿意，能够报答得了春天阳光的普照恩情呢？",
