    "spokenText": "从军行，王昌龄，唐代。青海长云暗雪山，孤城遥望玉门关。黄沙百战穿金甲，不破楼兰终不还。",
    "translation": "青海湖上空连绵的乌云笼罩着阴暗的祁连雪山，边塞孤城远远守望着玉门雄关。塞外狂沙中经历百战磨穿了铁甲战铠，不彻底平定边患就誓死不回家乡！",
    "appreciation": "充满慷慨激昂与誓死卫国的豪迈气魄。",
