    "spokenText": "秋夜将晓出篱门迎凉有感，陆游，宋代。三万里河东入海，五千仞岳上摩天。遗民泪尽胡尘里，南望王师又一年。",
    "translation": "三万里黄河滔滔向东奔流入海，五千仞华岳巍峨挺拔直插青天。中原失地受苦的老百姓在金兵铁蹄尘暴中哭干了眼泪，盼望朝廷北伐大军南望了一年又一年！",
    "appreciation": "山河壮丽与同胞苦难形成巨大反差，悲痛深沉。",
