    "spokenText": "凉州词，王之涣，唐代。黄河远上白云间，一片孤城万仞山。羌笛何须怨杨柳，春风不度玉门关。",
    "translation": "黄河奔腾宛如从白云之间迢迢而来，群峰崇山之间兀立着一座边塞孤城。何必用羌笛幽怨地吹奏《折杨柳》呢？春天的温暖之风本就吹不到这遥远的玉门关外。",
    "appreciation": "雄浑苍凉的边塞名篇，意境宏阔，沉郁高亢。",
