    "spokenText": "黄鹤楼送孟浩然之广陵，李白，唐代。故人西辞黄鹤楼，烟花三月下扬州。孤帆远影碧空尽，唯见长江天际流。",
    "translation": "老朋友孟浩然在西面的黄鹤楼与我依依告别，在繁花如锦的阳春三月顺流东下扬州。孤独的帆影渐渐消失在碧蓝的天空尽头，只看见浩瀚长江滚滚向天际奔流。",
    "appreciation": "将离别深情完全融入浩渺壮丽的长江水色之中。",
