    "translation": "老朋友准备了丰盛的鸡肉和黄米饭，邀请我到他的农家做客。翠绿的树木环抱着村落，秀丽的青山在城郭外横斜。打开窗子正对着打谷场和菜园，端起酒杯畅谈着庄稼农事。等到九月九日重阳节那天，我还要再来这里观赏菊花！",
