    "spokenText": "浪淘沙其一，刘禹锡，唐代。九曲黄河万里沙，浪淘风簸自天涯。如今直上银河去，同到牵牛织女家。",
    "translation": "九曲回转的黄河卷带着万里泥沙，狂风大浪颠簸着从天涯尽头奔腾而来。今天就让我们乘风破浪直上天上的银河去，一同探访那神话中的牵牛织女家吧！",
    "appreciation": "把黄河的雄浑磅礴与浪漫神话幻想完美结合，气冲斗牛。",
    "keywords": [
      {
        "word": "浪淘风簸",
        "explain": "波浪冲刷，狂风颠簸。"
      },
      {
        "word": "天涯",
        "explain": "天边尽头。"
      }
    ]
