    "spokenText": "寒食，韩翃，唐代。春城无处不飞花，寒食东风御柳斜。日暮汉宫传蜡烛，轻烟散入五侯家。",
    "translation": "暮春长安城里到处飘散着落花，寒食节东风吹拂御花园的杨柳轻斜。傍晚皇宫中分赐传点新蜡烛，袅袅轻烟飘散进豪门贵戚的府邸之中。",
    "appreciation": "以轻柔工丽的笔触，委婉讽喻唐代宦官权贵的特权恩宠。",
