    "spokenText": "十五夜望月，王建，唐代。中庭地白树栖鸦，冷露无声湿桂花。今夜月明人尽望，不知秋思落谁家。",
    "translation": "庭院月光洒满地面一片银白，乌鸦栖息在树枝上，无声的寒露悄悄打湿了桂花。今夜普天之下的人都在抬头仰望这一轮明月，不知这漫漫秋夜思念落入了谁的心中。",
    "appreciation": "中秋望月怀乡绝唱，不直说自己思乡，而问“不知秋思落谁家”，含蓄蕴藉。",
    "keywords": [
      {
        "word": "地白",
        "explain": "月光洒在地上像一层白霜。"
      },
      {
        "word": "秋思",
        "explain": "秋夜思亲念友之情。"
      }
    ]
