    "spokenText": "马诗，李贺，唐代。大漠沙如雪，燕山月似钩。何当金络脑，快走踏清秋。",
    "translation": "无边广漠中的黄沙在月下洁白如雪，燕山夜空挂着一弯如铁钩般的弯月。什么时候才能配上金色的笼头马嚼，纵横奔驰踏过那辽阔爽朗的深秋！",
    "appreciation": "借良马渴望驰骋边疆、建功立业，寄托了诗人渴望施展抱负的凌云壮志。",
