    "translation": "经历了千万次铁锤敲打钢凿开采才从深山运出，面对熊熊烈火的焚烧淬炼也看作平常等闲。纵然被研磨成粉身骨碎骨也浑然不惧，一定要把纯洁清白的品行永留在天地人间！",
