    "translation": "回想当初我出征时，杨柳依依随风摇曳。如今我返回家乡路途，雪花漫天纷扬飘落。泥泞道路行走缓慢艰难，又渴又饥忍受折磨。我的心中充满无尽悲伤，没人能理解我的哀痛！",
