    "spokenText": "别董大，高适，唐代。千里黄云白日曛，北风吹雁雪纷纷。莫愁前路无知己，天下谁人不识君？",
    "translation": "千里黄云密布太阳变得昏黄暗淡，北风呼啸大雁掠过大雪纷飞。不要担心未来的道路上没有知心朋友，试问天下又有谁不知道您的大名呢？",
    "appreciation": "慷慨悲壮中饱含深情厚谊与豪迈鼓励，送别诗中的豪迈绝唱。",
